-- insert_indicator-catalog.sql
-- Canonical indicator catalog for the Bundestagswahl "Strukturdaten der Wahlkreise".
-- Generated from the four source files in additional-data/strukturdaten/:
--   btw2013_strukturdaten.csv (39 data columns), btw2017_strukturdaten.csv (48),
--   btw2021_strukturdaten.csv (48), btw2025_strukturdaten.csv (48).
-- indicator: one row per canonical indicator (same real-world measure across years).
-- indicator_source_column: one row per (election_year, Spalten-Nr) data column of every
--   source file, with the exact original column label and the reference date embedded in it
--   (ISO YYYY-MM-DD; YYYY-MM if only a month is given, YYYY if only a year).
-- Labor-market indicators (ids 80-99) are Bundesagentur fuer Arbeit raw data
-- (source note in the 2017/2021/2025 files: "Quelle der Rohdaten der Spalten 35 bis 48").


-- Bundestagswahl 2013 : 39 data columns

-- Bundestagswahl 2017 : 48 data columns

-- Bundestagswahl 2021 : 48 data columns

-- Bundestagswahl 2025 : 48 data columns

